INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000065',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about past events","Use last week/month markers","Understand Perfekt overview"],"explanation":{"intro":"Welcome to A2! At this level you will learn to communicate more complex ideas — talking about the past, giving opinions, and using subordinate clauses.","culturalNote":"The Perfekt tense is used in spoken German for almost all past events, replacing the simple past (Präteritum) which is mainly used in writing and for sein/haben/modals."},"examples":[{"german":"Letzte Woche war ich in Berlin.","english":"Last week I was in Berlin."},{"german":"Was hast du am Wochenende gemacht?","english":"What did you do at the weekend?"}],"rewards":{"xp":120,"coins":60},"metadata":{"estimatedMinutes":15,"canDo":"I can talk about past events using time markers."}}',
'{"items":[{"word":"letzte Woche","translation":"last week","pronunciation":"LETS-teh VOH-khe","example":"Letzte Woche war ich krank."},{"word":"letzten Monat","translation":"last month","pronunciation":"LETS-ten MOH-naht","example":"Letzten Monat reiste ich."},{"word":"vorgestern","translation":"the day before yesterday","pronunciation":"FOR-ges-tern","example":"Vorgestern war Montag."},{"word":"damals","translation":"back then","pronunciation":"DAH-mahls","example":"Damals lebte ich anders."},{"word":"früher","translation":"in the past/formerly","pronunciation":"FRÜ-er","example":"Früher war alles anders."},{"word":"passieren","translation":"to happen","pronunciation":"pah-SEER-en","example":"Was ist passiert?"}]}',
'{"title":"Zeit-Adverbien — past time markers","pattern":"gestern / letzte Woche / letzten Monat / früher","explanation":"Time markers place events in the past. Gestern = yesterday. Letzte Woche = last week (letzte + feminine). Letzten Monat = last month (letzten + masculine). Früher = in the past (used for habitual past). Damals = back then (used for a specific past era).","examples":[{"sentence":"Gestern war ich im Kino.","translation":"Yesterday I was at the cinema."},{"sentence":"Früher habe ich viel Sport gemacht.","translation":"In the past I did a lot of sport."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Früher'' means?","options":["in the past","earlier (same day)","before","long ago"],"correctAnswer":"in the past"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Last week I was in Berlin.","options":["Letzte Woche war ich in Berlin.","Gestern war ich krank.","Damals lebte ich dort.","Was ist passiert?"],"correctAnswer":"Letzte Woche war ich in Berlin."},{"id":"ex3","type":"FILL_IN_BLANK","question":"___ Monat war ich in München.","options":["Letzten","Letzte","Letztes","Letzter"],"correctAnswer":"Letzten"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: What happened?","wordBankItems":["Was","ist","passiert","?"],"correctAnswer":"Was ist passiert ?"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Vorgestern'' means?","options":["day before yesterday","yesterday","last week","two days ago"],"correctAnswer":"day before yesterday"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000066',1,'APPROVED','PUBLISHED',
'{"objectives":["Form the Perfekt with haben","Use past participles","Say what you have done"],"explanation":{"intro":"The Perfekt is the main past tense in spoken German. It is formed with haben/sein + past participle. This lesson focuses on verbs with haben.","culturalNote":"The Perfekt is so dominant in spoken German that even educated native speakers rarely use Präteritum in conversation (except for sein, haben, and modals)."},"examples":[{"german":"Ich habe Deutsch gelernt.","english":"I have learned/learned German."},{"german":"Sie hat den Film gesehen.","english":"She has seen/saw the film."}],"rewards":{"xp":120,"coins":60},"metadata":{"estimatedMinutes":15,"canDo":"I can form the Perfekt with haben and talk about completed actions."}}',
'{"items":[{"word":"gelernt","translation":"learned (past participle)","pronunciation":"geh-LERNT","example":"Ich habe gelernt."},{"word":"gesehen","translation":"seen (past participle)","pronunciation":"geh-ZEY-en","example":"Ich habe gesehen."},{"word":"gemacht","translation":"done/made (past participle)","pronunciation":"geh-MAKHT","example":"Was hast du gemacht?"},{"word":"geschrieben","translation":"written (past participle)","pronunciation":"geh-SHREE-ben","example":"Ich habe geschrieben."},{"word":"gegessen","translation":"eaten (past participle)","pronunciation":"geh-GES-en","example":"Ich habe gegessen."},{"word":"getrunken","translation":"drunk (past participle)","pronunciation":"geh-TROONG-ken","example":"Ich habe Wasser getrunken."}]}',
'{"title":"Perfekt with haben — ge-...-t/en","pattern":"haben + ge- + verb stem + -t (weak) or ge-...-en (strong)","explanation":"Regular (weak) verbs: machen → gemacht, lernen → gelernt (ge- + stem + t). Irregular (strong) verbs change the stem: sehen → gesehen, essen → gegessen. The participle goes to the end. Ich habe Deutsch gelernt. Er hat den Film gesehen.","examples":[{"sentence":"Wir haben Pizza gegessen.","translation":"We ate/have eaten pizza."},{"sentence":"Du hast gut gespielt.","translation":"You played/have played well."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"Past participle of ''machen'' is?","options":["gemacht","gemacht","gemachtet","hat gemacht"],"correctAnswer":"gemacht"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I have learned German.","options":["Ich habe Deutsch gelernt.","Ich lerne Deutsch.","Ich lernte Deutsch.","Deutsch lernen."],"correctAnswer":"Ich habe Deutsch gelernt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Sie hat den Film ___.","options":["gesehen","sehen","gesieht","sah"],"correctAnswer":"gesehen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: We have eaten pizza","wordBankItems":["Wir","haben","Pizza","gegessen","."],"correctAnswer":"Wir haben Pizza gegessen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"Past participle of ''trinken'' is?","options":["getrunken","getrinkt","trank","getränkt"],"correctAnswer":"getrunken"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000067',1,'APPROVED','PUBLISHED',
'{"objectives":["Form Perfekt with sein","Know which verbs take sein","Use motion and change of state verbs"],"explanation":{"intro":"Some verbs use sein (not haben) in the Perfekt. These are mainly verbs of motion or change of state. This is one of the most important distinctions in German grammar.","culturalNote":"The rule: verbs that express movement from A to B (fahren, gehen, fliegen) or a change of state (aufwachen, werden, sterben) take sein. All others take haben."},"examples":[{"german":"Ich bin nach Berlin gefahren.","english":"I drove/have driven to Berlin."},{"german":"Er ist aufgewacht.","english":"He woke up."}],"rewards":{"xp":120,"coins":60},"metadata":{"estimatedMinutes":15,"canDo":"I can form the Perfekt with sein and know which verbs use it."}}',
'{"items":[{"word":"gefahren","translation":"driven/gone (by vehicle)","pronunciation":"geh-FAH-ren","example":"Ich bin gefahren."},{"word":"gegangen","translation":"gone/walked","pronunciation":"geh-GANG-en","example":"Ich bin gegangen."},{"word":"geflogen","translation":"flown","pronunciation":"geh-FLOH-gen","example":"Ich bin geflogen."},{"word":"aufgewacht","translation":"woken up","pronunciation":"OWF-geh-vakht","example":"Ich bin aufgewacht."},{"word":"angekommen","translation":"arrived","pronunciation":"AN-geh-kom-en","example":"Ich bin angekommen."},{"word":"passiert","translation":"happened","pronunciation":"pah-SEERT","example":"Es ist passiert."}]}',
'{"title":"Sein-Perfekt — motion and change of state","pattern":"sein + past participle (movement A→B, change of state)","explanation":"Movement verbs use sein: gehen → bin gegangen, fahren → bin gefahren, fliegen → bin geflogen. Change of state: aufwachen → bin aufgewacht, werden → bin geworden. Always: Es ist passiert (it happened) — passieren uses sein. Test: can you say it arrived/moved somewhere? Use sein.","examples":[{"sentence":"Sie ist nach Wien geflogen.","translation":"She flew to Vienna."},{"sentence":"Wir sind um 8 Uhr angekommen.","translation":"We arrived at 8 o''clock."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"Perfekt of ''gehen'' uses which auxiliary?","options":["sein","haben","both","neither"],"correctAnswer":"sein"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I drove to Berlin.","options":["Ich bin nach Berlin gefahren.","Ich habe Berlin gefahren.","Ich fuhr Berlin.","Ich fahre nach Berlin."],"correctAnswer":"Ich bin nach Berlin gefahren."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ich ___ aufgewacht.","options":["bin","habe","war","wurde"],"correctAnswer":"bin"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: She flew to Vienna","wordBankItems":["Sie","ist","nach","Wien","geflogen","."],"correctAnswer":"Sie ist nach Wien geflogen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Angekommen'' is the participle of?","options":["ankommen","kommen","hinkommmen","aufkommen"],"correctAnswer":"ankommen"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000068',1,'APPROVED','PUBLISHED',
'{"objectives":["Tell a simple life story","Use past tenses in sequence","Describe key life events"],"explanation":{"intro":"Being able to tell your life story is a key A2 skill. You use the Perfekt for completed events and war/hatte for background states.","culturalNote":"In German job interviews and social situations, you are often asked to erzählen Sie von sich (tell us about yourself). A clear Lebenslauf (CV) structure is important."},"examples":[{"german":"Ich bin 1990 in Stuttgart geboren.","english":"I was born in Stuttgart in 1990."},{"german":"Nach der Schule habe ich studiert.","english":"After school I studied."}],"rewards":{"xp":120,"coins":60},"metadata":{"estimatedMinutes":15,"canDo":"I can tell a simple life story using past tenses."}}',
'{"items":[{"word":"geboren","translation":"born","pronunciation":"geh-BOH-ren","example":"Ich bin geboren."},{"word":"aufgewachsen","translation":"grown up","pronunciation":"OWF-geh-vak-sen","example":"Ich bin aufgewachsen."},{"word":"studieren","translation":"to study (at university)","pronunciation":"shtoo-DEER-en","example":"Ich habe studiert."},{"word":"heiraten","translation":"to marry","pronunciation":"HY-rah-ten","example":"Wir haben geheiratet."},{"word":"umgezogen","translation":"moved (house)","pronunciation":"oom-geh-TSOH-gen","example":"Ich bin umgezogen."},{"word":"der Lebenslauf","translation":"CV/life story","pronunciation":"dayr LAY-bens-lowf","example":"Mein Lebenslauf."}]}',
'{"title":"Geboren sein — passive-looking sein constructions","pattern":"ich bin geboren / ich bin aufgewachsen","explanation":"Some expressions look like passive but function as Perfekt. Ich bin geboren = I was born (state reached). Ich bin aufgewachsen = I grew up. These use sein + participle. Ich bin in Berlin geboren = I was born in Berlin. This is fixed phrasing — learn as chunks.","examples":[{"sentence":"Sie ist in München aufgewachsen.","translation":"She grew up in Munich."},{"sentence":"Er ist 1985 geboren.","translation":"He was born in 1985."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Aufgewachsen'' means?","options":["grown up","grown","increased","matured"],"correctAnswer":"grown up"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I was born in Stuttgart in 1990.","options":["Ich bin 1990 in Stuttgart geboren.","Ich wurde 1990 geboren.","Ich bin 1990 aufgewachsen.","Ich lebe in Stuttgart."],"correctAnswer":"Ich bin 1990 in Stuttgart geboren."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Sie ___ in München aufgewachsen.","options":["ist","hat","war","wurde"],"correctAnswer":"ist"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: After school I studied","wordBankItems":["Nach","der","Schule","habe","ich","studiert","."],"correctAnswer":"Nach der Schule habe ich studiert ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Heiraten'' means?","options":["to marry","to date","to meet","to love"],"correctAnswer":"to marry"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000069',1,'APPROVED','PUBLISHED',
'{"objectives":["Describe childhood memories","Use früher and als kind","Express habitual past with früher"],"explanation":{"intro":"Talking about childhood in German is a great way to practice past tenses and get to know someone. Use früher (in the past) and als Kind (as a child).","culturalNote":"German children often play outdoors and take part in Verein activities from an early age. Kindergarten (literally children''s garden) is a German invention."},"examples":[{"german":"Als Kind habe ich viel gespielt.","english":"As a child I played a lot."},{"german":"Früher war ich sehr schüchtern.","english":"I used to be very shy."}],"rewards":{"xp":120,"coins":60},"metadata":{"estimatedMinutes":15,"canDo":"I can describe childhood memories and use früher correctly."}}',
'{"items":[{"word":"als Kind","translation":"as a child","pronunciation":"ahls KINT","example":"Als Kind liebte ich..."},{"word":"schüchtern","translation":"shy","pronunciation":"SHÜKH-tern","example":"Ich war schüchtern."},{"word":"frech","translation":"cheeky/naughty","pronunciation":"FREKH","example":"Ich war frech."},{"word":"neugierig","translation":"curious","pronunciation":"NOY-geer-ikh","example":"Sehr neugierig!"},{"word":"die Kindheit","translation":"childhood","pronunciation":"dee KINT-hyt","example":"Schöne Kindheit."},{"word":"aufwachsen","translation":"to grow up","pronunciation":"OWF-vak-sen","example":"Ich bin aufgewachsen."}]}',
'{"title":"Früher + war/hatte — habitual past","pattern":"früher war ich / früher hatte ich / früher habe ich ... gemacht","explanation":"Früher used with war (was) or hatte (had) describes how things used to be: Früher war ich schüchtern = I used to be shy. Früher hatte ich ein Fahrrad = I used to have a bike. For actions: Früher habe ich viel gespielt = I used to play a lot.","examples":[{"sentence":"Früher waren wir gute Freunde.","translation":"We used to be good friends."},{"sentence":"Als Kind hatte ich viele Haustiere.","translation":"As a child I had many pets."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Schüchtern'' means?","options":["shy","quiet","serious","gentle"],"correctAnswer":"shy"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"As a child I played a lot.","options":["Als Kind habe ich viel gespielt.","Früher war ich Kind.","Ich spielte viel.","Als Kind war ich gut."],"correctAnswer":"Als Kind habe ich viel gespielt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Früher ___ ich sehr schüchtern.","options":["war","bin","habe","hatte"],"correctAnswer":"war"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Beautiful childhood","wordBankItems":["Schöne","Kindheit","."],"correctAnswer":"Schöne Kindheit ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Neugierig'' means?","options":["curious","interested","excited","nosy"],"correctAnswer":"curious"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000006a',1,'APPROVED','PUBLISHED',
'{"objectives":["Describe your school experience","Talk about subjects","Use gern/nicht gern in past"],"explanation":{"intro":"School vocabulary lets you describe your education and share memories. German school has specific features worth knowing.","culturalNote":"German schools have three tracks: Hauptschule, Realschule, and Gymnasium. Gymnasium leads to the Abitur (A-levels equivalent) needed for university entry."},"examples":[{"german":"Mein Lieblingsfach war Mathematik.","english":"My favourite subject was Maths."},{"german":"Ich bin auf das Gymnasium gegangen.","english":"I went to grammar school."}],"rewards":{"xp":120,"coins":60},"metadata":{"estimatedMinutes":15,"canDo":"I can describe my school experience in German."}}',
'{"items":[{"word":"das Lieblingsfach","translation":"favourite subject","pronunciation":"dahs LEEB-lings-fakh","example":"Was ist dein Lieblingsfach?"},{"word":"die Mathematik","translation":"mathematics","pronunciation":"dee mah-teh-mah-TEK","example":"Ich mag Mathe."},{"word":"die Fremdsprache","translation":"foreign language","pronunciation":"dee FREMD-shprah-kheh","example":"Eine Fremdsprache lernen."},{"word":"die Note","translation":"grade/mark","pronunciation":"dee NOH-teh","example":"Eine gute Note."},{"word":"das Zeugnis","translation":"school report","pronunciation":"dahs TSOYG-nis","example":"Das Zeugnis ist gut."},{"word":"sitzen bleiben","translation":"to repeat a year","pronunciation":"ZIT-sen BLY-ben","example":"Ich bin sitzen geblieben."}]}',
'{"title":"Mein Liebling... — compound nouns for favourites","pattern":"mein Liebling + s + noun (Lieblingsfach, Lieblingsfilm)","explanation":"German forms favourite nouns by adding Liebling (favourite) + connecting -s- + noun. Lieblingsfach (favourite subject), Lieblingsfilm (favourite film), Lieblingsessen (favourite food). Always neuter das with these compounds unless the second noun determines gender.","examples":[{"sentence":"Mein Lieblingsfilm ist...","translation":"My favourite film is..."},{"sentence":"Was ist dein Lieblingsessen?","translation":"What is your favourite food?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Das Zeugnis'' means?","options":["school report","grade","test","certificate"],"correctAnswer":"school report"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"My favourite subject was Maths.","options":["Mein Lieblingsfach war Mathematik.","Ich mag Mathe gern.","Die Note war gut.","Ich habe Mathe studiert."],"correctAnswer":"Mein Lieblingsfach war Mathematik."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ich bin auf das ___ gegangen.","options":["Gymnasium","Schule","Realschule","Kindergarten"],"correctAnswer":"Gymnasium"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: A good grade","wordBankItems":["Eine","gute","Note","."],"correctAnswer":"Eine gute Note ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Sitzen bleiben'' means?","options":["to repeat a year","to stay seated","to fail","to drop out"],"correctAnswer":"to repeat a year"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000006b',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about relationships","Describe falling in love","Use kennenlernen and verlieben"],"explanation":{"intro":"Talking about relationships and love is important for personal conversation. Learn the key vocabulary for describing romantic experiences.","culturalNote":"Germans tend to be more reserved about starting new relationships compared to some other cultures. Getting to know someone over time (kennenlernen) before commitment is common."},"examples":[{"german":"Wir haben uns kennengelernt.","english":"We got to know each other."},{"german":"Ich habe mich in ihn verliebt.","english":"I fell in love with him."}],"rewards":{"xp":120,"coins":60},"metadata":{"estimatedMinutes":15,"canDo":"I can talk about relationships and falling in love in German."}}',
'{"items":[{"word":"sich verlieben","translation":"to fall in love","pronunciation":"zikh fer-LEE-ben","example":"Ich habe mich verliebt."},{"word":"kennenlernen","translation":"to get to know","pronunciation":"KEN-en-ler-nen","example":"Wir haben uns kennengelernt."},{"word":"der Freund","translation":"boyfriend/friend (m)","pronunciation":"dayr FROYNT","example":"Mein Freund ist nett."},{"word":"die Freundin","translation":"girlfriend/friend (f)","pronunciation":"dee FROYN-din","example":"Meine Freundin."},{"word":"sich küssen","translation":"to kiss each other","pronunciation":"zikh KÜS-en","example":"Wir haben uns geküsst."},{"word":"die Beziehung","translation":"relationship","pronunciation":"dee beh-TSEE-hoong","example":"Eine gute Beziehung."}]}',
'{"title":"Sich verlieben — reflexive with in + accusative","pattern":"sich verlieben in + accusative","explanation":"Sich verlieben takes in + accusative: Ich habe mich in ihn verliebt (I fell in love with him). The reflexive is mich (accusative). Compare: sich in jemanden verlieben = to fall in love with someone. In Perfekt: habe mich verliebt.","examples":[{"sentence":"Er hat sich in sie verliebt.","translation":"He fell in love with her."},{"sentence":"Wann habt ihr euch kennengelernt?","translation":"When did you two get to know each other?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Beziehung'' means?","options":["relationship","connection","attraction","bond"],"correctAnswer":"relationship"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I fell in love with him.","options":["Ich habe mich in ihn verliebt.","Wir haben uns kennengelernt.","Ich liebe ihn.","Er ist mein Freund."],"correctAnswer":"Ich habe mich in ihn verliebt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Wir haben uns ___.","options":["kennengelernt","kennen gelernt","gelernt kennen","kennen"],"correctAnswer":"kennengelernt"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: A good relationship","wordBankItems":["Eine","gute","Beziehung","."],"correctAnswer":"Eine gute Beziehung ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Sich verlieben'' uses which case for the person?","options":["accusative (in ihn)","dative (mit ihm)","genitive","nominative"],"correctAnswer":"accusative (in ihn)"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000006c',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about starting a job","Describe your profession more precisely","Use anfangen and beginnen"],"explanation":{"intro":"Career vocabulary at A2 goes beyond just naming jobs. You can now describe career paths, starting work, and workplace relationships.","culturalNote":"The German apprenticeship system (Berufsausbildung) is world-famous. It combines workplace training with part-time school over 2-3 years and leads to highly respected qualifications."},"examples":[{"german":"Ich habe eine Stelle als Buchhalter gefunden.","english":"I found a job as an accountant."},{"german":"Meine Ausbildung hat zwei Jahre gedauert.","english":"My apprenticeship lasted two years."}],"rewards":{"xp":120,"coins":60},"metadata":{"estimatedMinutes":15,"canDo":"I can talk about starting a job and describe career paths."}}',
'{"items":[{"word":"die Stelle","translation":"job/position","pronunciation":"dee SHTEL-leh","example":"Eine Stelle suchen."},{"word":"die Ausbildung","translation":"vocational training/apprenticeship","pronunciation":"dee OWS-bil-doong","example":"Eine Ausbildung machen."},{"word":"der Kollege","translation":"colleague (m)","pronunciation":"dayr kol-EY-geh","example":"Meine Kollegen."},{"word":"die Abteilung","translation":"department","pronunciation":"dee ap-TY-loong","example":"Ich arbeite in der Abteilung."},{"word":"der Chef","translation":"boss/manager","pronunciation":"dayr SHEF","example":"Mein Chef ist streng."},{"word":"die Gehaltserhöhung","translation":"pay rise","pronunciation":"dee geh-HALTS-er-hö-oong","example":"Eine Gehaltserhöhung bekommen."}]}',
'{"title":"Dauern — expressing duration","pattern":"etwas dauert + time period","explanation":"Dauern (to last) expresses how long something takes. Die Ausbildung dauert zwei Jahre = The training lasts two years. Wie lange dauert das? = How long does that take? Use dauern + accusative time span (not von...bis which uses prepositions).","examples":[{"sentence":"Der Zug fährt zwei Stunden.","translation":"The train takes two hours."},{"sentence":"Wie lange hat das gedauert?","translation":"How long did that take?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Abteilung'' means?","options":["department","office","division","floor"],"correctAnswer":"department"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"My apprenticeship lasted two years.","options":["Meine Ausbildung hat zwei Jahre gedauert.","Ich habe eine Stelle.","Mein Chef ist nett.","Ich habe studiert."],"correctAnswer":"Meine Ausbildung hat zwei Jahre gedauert."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Wie lange hat das ___?","options":["gedauert","dauert","dauern","gedauere"],"correctAnswer":"gedauert"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I am looking for a job","wordBankItems":["Ich","suche","eine","Stelle","."],"correctAnswer":"Ich suche eine Stelle ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Gehaltserhöhung'' means?","options":["pay rise","salary","bonus","overtime"],"correctAnswer":"pay rise"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000006d',1,'APPROVED','PUBLISHED',
'{"objectives":["Describe extended family","Talk about family relationships","Use genitive for family possession"],"explanation":{"intro":"Extended family vocabulary builds on the basics. Learn to describe cousins, grandparents, in-laws and more complex family structures.","culturalNote":"German families tend to be close. Grandparents often help with childcare. Sunday family lunches (Sonntagsessen) are a tradition in many households."},"examples":[{"german":"Meine Schwägerin ist sehr nett.","english":"My sister-in-law is very nice."},{"german":"Ich habe vier Cousins.","english":"I have four cousins."}],"rewards":{"xp":120,"coins":60},"metadata":{"estimatedMinutes":15,"canDo":"I can describe extended family relationships in German."}}',
'{"items":[{"word":"die Schwiegermutter","translation":"mother-in-law","pronunciation":"dee SHVEE-ger-moo-ter","example":"Meine Schwiegermutter."},{"word":"der Schwager","translation":"brother-in-law","pronunciation":"dayr SHVAH-ger","example":"Mein Schwager."},{"word":"die Schwägerin","translation":"sister-in-law","pronunciation":"dee SHVÄ-geh-rin","example":"Meine Schwägerin."},{"word":"der Cousin","translation":"cousin (m)","pronunciation":"dayr koo-ZAN","example":"Mein Cousin."},{"word":"die Cousine","translation":"cousin (f)","pronunciation":"dee koo-ZEE-neh","example":"Meine Cousine."},{"word":"der Neffe","translation":"nephew","pronunciation":"dayr NEF-feh","example":"Mein Neffe."}]}',
'{"title":"Possessive adjectives — mein/dein/sein/ihr","pattern":"mein (m/n) / meine (f/pl) + family member","explanation":"Possessives agree with the gender of the noun, not the possessor. Mein Bruder (masculine noun). Meine Schwester (feminine noun). Mein Kind (neuter). Meine Eltern (plural). Common error: saying mein Schwester — it must be meine.","examples":[{"sentence":"Meine Schwiegermutter wohnt in Bayern.","translation":"My mother-in-law lives in Bavaria."},{"sentence":"Sein Cousin ist Arzt.","translation":"His cousin is a doctor."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Der Neffe'' means?","options":["nephew","niece","cousin","uncle"],"correctAnswer":"nephew"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"My sister-in-law is very nice.","options":["Meine Schwägerin ist sehr nett.","Mein Schwager ist freundlich.","Meine Cousine ist nett.","Meine Schwiegermutter ist gut."],"correctAnswer":"Meine Schwägerin ist sehr nett."},{"id":"ex3","type":"FILL_IN_BLANK","question":"___ Cousin ist Arzt.","options":["Mein","Meine","Meinen","Meinem"],"correctAnswer":"Mein"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I have four cousins","wordBankItems":["Ich","habe","vier","Cousins","."],"correctAnswer":"Ich habe vier Cousins ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Schwiegermutter'' means?","options":["mother-in-law","stepmother","grandmother","aunt"],"correctAnswer":"mother-in-law"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000006e',1,'APPROVED','PUBLISHED',
'{"objectives":["Describe your home town","Compare cities and towns","Use Es gibt in a town description"],"explanation":{"intro":"Describing where you live is a core A2 topic. Learn to talk about your town''s features, size and character.","culturalNote":"Germany has 82 cities with over 100,000 inhabitants. Most Germans live in mid-sized towns. Each region has its own distinct identity, dialect and cuisine."},"examples":[{"german":"Ich wohne in einer Kleinstadt.","english":"I live in a small town."},{"german":"In meiner Stadt gibt es viele Museen.","english":"In my town there are many museums."}],"rewards":{"xp":120,"coins":60},"metadata":{"estimatedMinutes":15,"canDo":"I can describe my home town and its features."}}',
'{"items":[{"word":"die Kleinstadt","translation":"small town","pronunciation":"dee KLYNE-shtaht","example":"Eine ruhige Kleinstadt."},{"word":"die Großstadt","translation":"big city","pronunciation":"dee GROHS-shtaht","example":"Berlin ist eine Großstadt."},{"word":"das Stadtviertel","translation":"neighbourhood/quarter","pronunciation":"dahs SHTAHT-feer-tel","example":"Mein Stadtviertel ist schön."},{"word":"lebhaft","translation":"lively","pronunciation":"LEYP-haft","example":"Sehr lebhaft."},{"word":"ruhig","translation":"quiet/peaceful","pronunciation":"ROO-ikh","example":"Ein ruhiges Viertel."},{"word":"das Wahrzeichen","translation":"landmark/symbol","pronunciation":"dahs VAR-tsy-khen","example":"Das Wahrzeichen der Stadt."}]}',
'{"title":"In meiner Stadt — dative location descriptions","pattern":"in meiner Stadt (f) / in meinem Ort (m) / in meinem Dorf (n)","explanation":"Location phrases use dative. In meiner Stadt = in my town (dative feminine). In meinem Ort = in my place (dative masculine). In meinem Dorf = in my village (dative neuter). The possessive adjective takes dative endings: mein → meinem (m/n), mein → meiner (f).","examples":[{"sentence":"In meiner Heimatstadt gibt es einen Dom.","translation":"In my home town there is a cathedral."},{"sentence":"Mein Stadtviertel ist sehr ruhig.","translation":"My neighbourhood is very quiet."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Lebhaft'' means?","options":["lively","busy","loud","active"],"correctAnswer":"lively"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"In my town there are many museums.","options":["In meiner Stadt gibt es viele Museen.","Meine Stadt ist groß.","Ich wohne in Berlin.","Das Wahrzeichen ist schön."],"correctAnswer":"In meiner Stadt gibt es viele Museen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ich wohne in ___ Kleinstadt.","options":["einer","eine","ein","einem"],"correctAnswer":"einer"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: My neighbourhood is beautiful","wordBankItems":["Mein","Stadtviertel","ist","schön","."],"correctAnswer":"Mein Stadtviertel ist schön ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Das Wahrzeichen'' means?","options":["landmark","monument","sign","symbol"],"correctAnswer":"landmark"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000006f',1,'APPROVED','PUBLISHED',
'{"objectives":["Make comparisons","Use größer/kleiner/besser","Form superlatives"],"explanation":{"intro":"Comparative and superlative are essential for comparing things. German comparatives add -er; superlatives use am ...-(e)sten.","culturalNote":"Comparative language appears constantly in German — in advertising (besser als, günstiger), sport commentary, weather reports and everyday conversation."},"examples":[{"german":"Berlin ist größer als Hamburg.","english":"Berlin is bigger than Hamburg."},{"german":"Das ist das beste Essen der Stadt.","english":"This is the best food in the city."}],"rewards":{"xp":120,"coins":60},"metadata":{"estimatedMinutes":15,"canDo":"I can make comparisons and use superlatives in German."}}',
'{"items":[{"word":"größer","translation":"bigger","pronunciation":"GRÖ-ser","example":"Viel größer!"},{"word":"kleiner","translation":"smaller","pronunciation":"KLY-ner","example":"Kleiner als gedacht."},{"word":"besser","translation":"better","pronunciation":"BES-er","example":"Viel besser!"},{"word":"schlechter","translation":"worse","pronunciation":"SHLEKH-ter","example":"Heute schlechter."},{"word":"am größten","translation":"biggest (superlative)","pronunciation":"am GRÖS-ten","example":"Am größten ist..."},{"word":"als","translation":"than (comparison)","pronunciation":"ahls","example":"Größer als Berlin."}]}',
'{"title":"Komparativ — adjective + -er + als","pattern":"adjective + -er + als (than)","explanation":"Comparative: add -er. Groß → größer (umlaut!). Klein → kleiner. Schnell → schneller. Berlin ist größer als Hamburg. Superlative: am + adjective + -sten. Am größten, am schnellsten. Irregular: gut → besser → am besten. Viel → mehr → am meisten.","examples":[{"sentence":"Sie spricht besser als ich.","translation":"She speaks better than me."},{"sentence":"Das ist die günstigste Option.","translation":"That is the cheapest option."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"Comparative of ''groß'' is?","options":["größer","groß-er","großer","am größten"],"correctAnswer":"größer"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Berlin is bigger than Hamburg.","options":["Berlin ist größer als Hamburg.","Hamburg ist kleiner.","Berlin ist am größten.","Größer als erwartet."],"correctAnswer":"Berlin ist größer als Hamburg."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das ist am ___.","options":["besten","besser","gut","beste"],"correctAnswer":"besten"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: She speaks better than me","wordBankItems":["Sie","spricht","besser","als","ich","."],"correctAnswer":"Sie spricht besser als ich ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"Superlative of ''gut'' is?","options":["am besten","am gutsten","am bessten","am gütigsten"],"correctAnswer":"am besten"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000070',1,'APPROVED','PUBLISHED',
'{"objectives":["Express opinions confidently","Use ich finde, ich denke, meiner Meinung nach","Give reasons"],"explanation":{"intro":"Expressing opinions is central to A2 conversation. German has several structured ways to give your view and support it with reasons.","culturalNote":"Germans appreciate direct, clear opinions. Hedging with vielleicht (perhaps) or ich glaube (I think) is common for uncertain opinions. Meiner Meinung nach (in my opinion) adds formality."},"examples":[{"german":"Meiner Meinung nach ist das falsch.","english":"In my opinion that is wrong."},{"german":"Ich finde, das ist eine gute Idee.","english":"I think that is a good idea."}],"rewards":{"xp":120,"coins":60},"metadata":{"estimatedMinutes":15,"canDo":"I can express opinions and give reasons in German."}}',
'{"items":[{"word":"meiner Meinung nach","translation":"in my opinion","pronunciation":"MY-ner MY-noong nakh","example":"Meiner Meinung nach..."},{"word":"ich finde","translation":"I find/think","pronunciation":"ikh FIN-deh","example":"Ich finde das gut."},{"word":"ich denke","translation":"I think","pronunciation":"ikh DEN-keh","example":"Ich denke, dass..."},{"word":"ich glaube","translation":"I believe/think","pronunciation":"ikh GLOW-beh","example":"Ich glaube schon."},{"word":"eigentlich","translation":"actually/in fact","pronunciation":"EY-gent-likh","example":"Eigentlich nicht."},{"word":"meistens","translation":"mostly/usually","pronunciation":"MYS-tens","example":"Meistens stimme ich zu."}]}',
'{"title":"Dass-Satz — dass clause for opinions","pattern":"ich finde/denke/glaube, dass + verb at end","explanation":"Opinion phrases are followed by dass (that) + subordinate clause. In dass clauses the verb goes to the end. Ich finde, dass das falsch ist. Ich denke, dass sie recht hat. This is a core A2 structure: dass triggers verb-final word order.","examples":[{"sentence":"Ich glaube, dass er kommt.","translation":"I think that he is coming."},{"sentence":"Ich finde, dass das zu teuer ist.","translation":"I think that is too expensive."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Eigentlich'' means?","options":["actually","usually","normally","really"],"correctAnswer":"actually"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"In my opinion that is wrong.","options":["Meiner Meinung nach ist das falsch.","Ich finde das gut.","Das stimmt nicht.","Ich glaube schon."],"correctAnswer":"Meiner Meinung nach ist das falsch."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ich finde, ___ das zu teuer ist.","options":["dass","das","weil","ob"],"correctAnswer":"dass"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I think that he is right","wordBankItems":["Ich","glaube",",","dass","er","recht","hat","."],"correctAnswer":"Ich glaube , dass er recht hat ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"In a dass-clause, where does the verb go?","options":["to the end","to the start","second position","unchanged"],"correctAnswer":"to the end"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000071',1,'APPROVED','PUBLISHED',
'{"objectives":["Agree and disagree politely","Use stimmt and das sehe ich anders","Maintain respectful discussion"],"explanation":{"intro":"Agreeing and disagreeing in German uses specific phrases. Learn to express agreement, partial agreement and polite disagreement.","culturalNote":"Germans tend to be direct in discussions. Disagreement is not personal — it is intellectual. Saying Das sehe ich anders (I see that differently) is completely normal and not rude."},"examples":[{"german":"Da hast du völlig Recht!","english":"You are absolutely right!"},{"german":"Das sehe ich ein bisschen anders.","english":"I see that a little differently."}],"rewards":{"xp":120,"coins":60},"metadata":{"estimatedMinutes":15,"canDo":"I can agree and disagree politely in German discussions."}}',
'{"items":[{"word":"Recht haben","translation":"to be right","pronunciation":"REKHT HAH-ben","example":"Du hast Recht."},{"word":"das sehe ich anders","translation":"I see that differently","pronunciation":"dahs ZEY-eh ikh AN-ders","example":"Das sehe ich anders."},{"word":"zustimmen","translation":"to agree","pronunciation":"TSOO-shtim-en","example":"Ich stimme zu."},{"word":"widersprechen","translation":"to disagree/contradict","pronunciation":"VEE-der-shpre-khen","example":"Ich widerspreche."},{"word":"einerseits","translation":"on one hand","pronunciation":"EY-ner-zyts","example":"Einerseits ja..."},{"word":"andererseits","translation":"on the other hand","pronunciation":"AN-de-rer-zyts","example":"Andererseits nein."}]}',
'{"title":"Einerseits/andererseits — presenting two sides","pattern":"einerseits ... andererseits ... (on one hand ... on the other)","explanation":"Use einerseits...andererseits to show balanced views. Einerseits ist das gut, andererseits ist es teuer. Both are sentence-initial adverbs that send the verb to position 2: Einerseits stimme ich zu = On one hand I agree.","examples":[{"sentence":"Einerseits ist Berlin toll, andererseits ist es sehr teuer.","translation":"On one hand Berlin is great, on the other it is very expensive."},{"sentence":"Da haben Sie absolut recht.","translation":"You are absolutely right about that."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Recht haben'' means?","options":["to be right","to have rights","to be correct","to agree"],"correctAnswer":"to be right"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I see that a little differently.","options":["Das sehe ich ein bisschen anders.","Ich stimme zu.","Du hast recht.","Das ist falsch."],"correctAnswer":"Das sehe ich ein bisschen anders."},{"id":"ex3","type":"FILL_IN_BLANK","question":"___ stimme ich zu, ___ nicht ganz.","options":["Einerseits...andererseits","Erstens...zweitens","Ja...nein","Aber...doch"],"correctAnswer":"Einerseits...andererseits"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: You are absolutely right!","wordBankItems":["Da","hast","du","völlig","Recht","!"],"correctAnswer":"Da hast du völlig Recht !"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Widersprechen'' means?","options":["to disagree","to agree","to interrupt","to correct"],"correctAnswer":"to disagree"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000072',1,'APPROVED','PUBLISHED',
'{"objectives":["Express likes and dislikes","Use lieben, mögen, hassen","Compare preferences with lieber"],"explanation":{"intro":"Expressing preferences goes beyond gern and nicht gern. Learn to express strong likes, dislikes and gradations of preference.","culturalNote":"Food preferences are a constant conversation topic in Germany. Dietary restrictions (vegetarian, vegan, gluten-free) are widely understood and catered for."},"examples":[{"german":"Ich liebe klassische Musik.","english":"I love classical music."},{"german":"Ich kann Lärm überhaupt nicht leiden.","english":"I cannot stand noise at all."}],"rewards":{"xp":120,"coins":60},"metadata":{"estimatedMinutes":15,"canDo":"I can express strong likes, dislikes and compare preferences."}}',
'{"items":[{"word":"lieben","translation":"to love","pronunciation":"LEE-ben","example":"Ich liebe dich."},{"word":"mögen","translation":"to like","pronunciation":"MÖ-gen","example":"Ich mag Kaffee."},{"word":"überhaupt nicht","translation":"not at all","pronunciation":"ü-ber-HOWPT nikht","example":"Überhaupt nicht gut."},{"word":"leiden können","translation":"to be able to stand (someone)","pronunciation":"LY-den KÖN-en","example":"Ich kann ihn nicht leiden."},{"word":"lieber","translation":"rather/prefer","pronunciation":"LEE-ber","example":"Ich trinke lieber Tee."},{"word":"am liebsten","translation":"most of all/prefer most","pronunciation":"am LEEB-sten","example":"Am liebsten Kaffee."}]}',
'{"title":"Gern / lieber / am liebsten — preference scale","pattern":"gern → lieber → am liebsten (like → prefer → like most)","explanation":"Gern, lieber, am liebsten form a preference scale. Ich trinke gern Kaffee (I like coffee). Ich trinke lieber Tee (I prefer tea). Ich trinke am liebsten Wasser (I like water most of all). Add these after the verb to express preference level.","examples":[{"sentence":"Ich esse lieber Fisch als Fleisch.","translation":"I prefer fish to meat."},{"sentence":"Was machst du am liebsten?","translation":"What do you like doing most?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Lieber'' means in preference context?","options":["rather/prefer","more lovingly","better","most"],"correctAnswer":"rather/prefer"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I love classical music.","options":["Ich liebe klassische Musik.","Ich mag Musik.","Ich höre gern Musik.","Musik ist toll."],"correctAnswer":"Ich liebe klassische Musik."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ich trinke ___ Tee als Kaffee.","options":["lieber","liebe","am liebsten","gern"],"correctAnswer":"lieber"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: What do you like most?","wordBankItems":["Was","machst","du","am","liebsten","?"],"correctAnswer":"Was machst du am liebsten ?"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Überhaupt nicht'' means?","options":["not at all","not really","hardly","never"],"correctAnswer":"not at all"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000073',1,'APPROVED','PUBLISHED',
'{"objectives":["Express wishes and dreams","Use Konjunktiv II für wishes","Use wenn ich... wäre/hätte"],"explanation":{"intro":"Expressing wishes and dreams uses the Konjunktiv II (subjunctive). This allows you to talk about hypothetical or desired states.","culturalNote":"Germans are known for being practical, but everyone has Träume (dreams). Phrases like Ich würde gern (I would like to) and Ich wünsche mir (I wish for) are common."},"examples":[{"german":"Ich würde gern nach Japan reisen.","english":"I would like to travel to Japan."},{"german":"Wenn ich Geld hätte, würde ich eine Villa kaufen.","english":"If I had money, I would buy a villa."}],"rewards":{"xp":120,"coins":60},"metadata":{"estimatedMinutes":15,"canDo":"I can express wishes and dreams using Konjunktiv II."}}',
'{"items":[{"word":"würde gern","translation":"would like to","pronunciation":"VÜR-deh GERN","example":"Ich würde gern reisen."},{"word":"sich wünschen","translation":"to wish for","pronunciation":"zikh VÜN-shen","example":"Ich wünsche mir Glück."},{"word":"der Traum","translation":"dream","pronunciation":"dayr TROWM","example":"Mein großer Traum."},{"word":"träumen","translation":"to dream","pronunciation":"TROY-men","example":"Ich träume davon."},{"word":"hätte","translation":"would have (Konj. II)","pronunciation":"HET-teh","example":"Wenn ich Zeit hätte."},{"word":"wäre","translation":"would be (Konj. II)","pronunciation":"VÄ-reh","example":"Wenn ich reich wäre."}]}',
'{"title":"Konjunktiv II — hätte and wäre","pattern":"wenn ich X hätte/wäre, würde ich Y","explanation":"Konjunktiv II for wishes: hätte = would have (Konj II of haben), wäre = would be (Konj II of sein). Wenn ich Zeit hätte = If I had time. Wenn ich reich wäre = If I were rich. The main clause uses würde + infinitive: würde ich reisen.","examples":[{"sentence":"Wenn ich fliegen könnte, würde ich die Welt sehen.","translation":"If I could fly, I would see the world."},{"sentence":"Ich wünsche mir mehr Freizeit.","translation":"I wish for more free time."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Wäre'' is the Konjunktiv II of?","options":["sein","werden","waren","wären"],"correctAnswer":"sein"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I would like to travel to Japan.","options":["Ich würde gern nach Japan reisen.","Ich reise nach Japan.","Ich will nach Japan.","Japan ist toll."],"correctAnswer":"Ich würde gern nach Japan reisen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Wenn ich Geld ___, würde ich eine Villa kaufen.","options":["hätte","habe","hatte","haben"],"correctAnswer":"hätte"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: My big dream","wordBankItems":["Mein","großer","Traum","."],"correctAnswer":"Mein großer Traum ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Träumen'' means?","options":["to dream","to wish","to imagine","to hope"],"correctAnswer":"to dream"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000074',1,'APPROVED','PUBLISHED',
'{"objectives":["Make and arrange plans","Suggest activities","Accept and decline invitations"],"explanation":{"intro":"Making plans in German involves suggesting, accepting, declining and rescheduling. These are everyday social skills.","culturalNote":"Germans appreciate punctuality and planning. Last-minute invitations (kurzfristig einladen) can sometimes catch people off guard. Advance planning is preferred in both social and professional contexts."},"examples":[{"german":"Hast du am Samstag Zeit?","english":"Do you have time on Saturday?"},{"german":"Ich würde gern mitkommen!","english":"I would love to come along!"}],"rewards":{"xp":120,"coins":60},"metadata":{"estimatedMinutes":15,"canDo":"I can make plans, accept and decline invitations in German."}}',
'{"items":[{"word":"vorschlagen","translation":"to suggest","pronunciation":"FOR-shlah-gen","example":"Ich schlage vor..."},{"word":"einladen","translation":"to invite","pronunciation":"YN-lah-den","example":"Ich lade dich ein."},{"word":"ablehnen","translation":"to decline","pronunciation":"AP-ley-nen","example":"Ich lehne leider ab."},{"word":"mitkommen","translation":"to come along","pronunciation":"MIT-kom-en","example":"Ich komme mit!"},{"word":"verschieben","translation":"to reschedule","pronunciation":"fer-SHEE-ben","example":"Können wir verschieben?"},{"word":"es passt mir","translation":"it suits me","pronunciation":"ES PAST meer","example":"Es passt mir gut."}]}',
'{"title":"Ich schlage vor, dass — suggesting with subordinate","pattern":"Ich schlage vor, dass wir + verb at end","explanation":"Vorschlagen (to suggest) often introduces a dass-clause. Ich schlage vor, dass wir ins Kino gehen = I suggest that we go to the cinema. Vorschlagen is separable: Ich schlage vor. Also: Wie wäre es mit...? = How about...? (How would it be with?)","examples":[{"sentence":"Ich schlage vor, dass wir wandern gehen.","translation":"I suggest that we go hiking."},{"sentence":"Wie wäre es mit einem Kinofilm?","translation":"How about a cinema film?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Ablehnen'' means?","options":["to decline","to accept","to postpone","to cancel"],"correctAnswer":"to decline"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I would love to come along!","options":["Ich würde gern mitkommen!","Ich komme nicht.","Es passt mir nicht.","Ich schlage vor."],"correctAnswer":"Ich würde gern mitkommen!"},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ich ___ dich ein.","options":["lade","lad","lädst","laden"],"correctAnswer":"lade"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Can we reschedule?","wordBankItems":["Können","wir","verschieben","?"],"correctAnswer":"Können wir verschieben ?"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Es passt mir'' means?","options":["it suits me","I like it","it is convenient","I agree"],"correctAnswer":"it suits me"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000075',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about future plans","Use werden for future","Use present tense for scheduled future"],"explanation":{"intro":"German uses two main ways to express the future: werden + infinitive (like will/shall) and simply the present tense with a future time marker.","culturalNote":"In spoken German the present tense with a time marker (morgen, nächste Woche) is more common than werden for future plans. Werden is used for predictions, promises and more formal future statements."},"examples":[{"german":"Ich werde morgen arbeiten.","english":"I will work tomorrow."},{"german":"Morgen fahre ich nach Hamburg.","english":"Tomorrow I am going to Hamburg."}],"rewards":{"xp":120,"coins":60},"metadata":{"estimatedMinutes":15,"canDo":"I can talk about future events using werden and present tense."}}',
'{"items":[{"word":"werden","translation":"will (future auxiliary)","pronunciation":"VER-den","example":"Ich werde lernen."},{"word":"nächste Woche","translation":"next week","pronunciation":"NEKHS-teh VOH-khe","example":"Nächste Woche bin ich weg."},{"word":"bald","translation":"soon","pronunciation":"BALT","example":"Das kommt bald."},{"word":"irgendwann","translation":"sometime/at some point","pronunciation":"EER-gend-van","example":"Irgendwann reise ich."},{"word":"planen","translation":"to plan","pronunciation":"PLAH-nen","example":"Ich plane eine Reise."},{"word":"vorhaben","translation":"to intend/plan","pronunciation":"FOR-hah-ben","example":"Was haben Sie vor?"}]}',
'{"title":"Werden + infinitive — Futur I","pattern":"werden + infinitive at end","explanation":"Futur I: werden conjugates + infinitive final. Ich werde kommen = I will come. Er wird arbeiten = He will work. Conjugation: ich werde, du wirst, er/sie/es wird, wir werden, ihr werdet, sie/Sie werden. Use for predictions: Es wird regnen = It will rain.","examples":[{"sentence":"Das wird schwierig.","translation":"That will be difficult."},{"sentence":"Wir werden uns wiedersehen.","translation":"We will see each other again."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Vorhaben'' means?","options":["to intend/plan","to prepare","to organise","to schedule"],"correctAnswer":"to intend/plan"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I will work tomorrow.","options":["Ich werde morgen arbeiten.","Ich arbeite morgen.","Ich habe morgen gearbeitet.","Morgen gehe ich."],"correctAnswer":"Ich werde morgen arbeiten."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Er ___ arbeiten.","options":["wird","werde","werden","wirst"],"correctAnswer":"wird"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: We will see each other again","wordBankItems":["Wir","werden","uns","wiedersehen","."],"correctAnswer":"Wir werden uns wiedersehen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Bald'' means?","options":["soon","later","eventually","when"],"correctAnswer":"soon"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000076',1,'APPROVED','PUBLISHED',
'{"objectives":["Express conditions","Use falls and wenn","Understand conditional structure"],"explanation":{"intro":"Conditional sentences (if-then) are essential for expressing conditions, warnings and hypothetical situations.","culturalNote":"Conditional language is common in polite requests (Wenn Sie Zeit haben...) and business language (Falls Sie Fragen haben...). Falls is slightly more formal than wenn for conditions."},"examples":[{"german":"Falls es regnet, bleiben wir zu Hause.","english":"If it rains, we will stay home."},{"german":"Wenn du krank bist, geh zum Arzt.","english":"If you are ill, go to the doctor."}],"rewards":{"xp":120,"coins":60},"metadata":{"estimatedMinutes":15,"canDo":"I can form conditional sentences with wenn and falls."}}',
'{"items":[{"word":"falls","translation":"in case/if (conditional)","pronunciation":"FALS","example":"Falls es klappt..."},{"word":"wenn","translation":"when/if","pronunciation":"VEN","example":"Wenn du kommst..."},{"word":"dann","translation":"then","pronunciation":"DAN","example":"Dann machen wir das."},{"word":"sonst","translation":"otherwise","pronunciation":"ZONST","example":"Sonst verpassen wir den Zug."},{"word":"vorausgesetzt","translation":"provided that","pronunciation":"for-OWS-geh-zetst","example":"Vorausgesetzt, das klappt."},{"word":"klappen","translation":"to work out/succeed","pronunciation":"KLAP-en","example":"Hat es geklappt?"}]}',
'{"title":"Wenn-Satz — conditional clause structure","pattern":"Wenn/Falls + [subordinate clause, verb last], + [main clause, verb first]","explanation":"Wenn/falls triggers verb-final order in the subordinate clause. Then the main clause starts with the verb. Wenn es regnet, bleiben wir zu Hause. Note the comma between clauses. Falls = if (condition, slight doubt). Wenn = when/if (more general).","examples":[{"sentence":"Wenn du Zeit hast, ruf mich an.","translation":"If you have time, call me."},{"sentence":"Falls es klappt, feiere ich.","translation":"If it works out, I will celebrate."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Sonst'' means?","options":["otherwise","then","also","but"],"correctAnswer":"otherwise"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"If it rains we stay home.","options":["Falls es regnet, bleiben wir zu Hause.","Wenn es kalt ist, gehe ich rein.","Dann bleiben wir.","Es regnet heute."],"correctAnswer":"Falls es regnet, bleiben wir zu Hause."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Wenn du Zeit ___, ruf mich an.","options":["hast","hat","haben","habst"],"correctAnswer":"hast"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Has it worked out?","wordBankItems":["Hat","es","geklappt","?"],"correctAnswer":"Hat es geklappt ?"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"In a wenn-clause, where does the verb go?","options":["to the end","to the start","second position","after wenn"],"correctAnswer":"to the end"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000077',1,'APPROVED','PUBLISHED',
'{"objectives":["Use wenn-clauses for conditions","Practise verb-final in subordinate clauses","Build complex sentences"],"explanation":{"intro":"Wenn-clauses (if/when clauses) are the most common type of subordinate clause in German. Mastering them opens up complex sentence building.","culturalNote":"Subordinate clauses are a key feature of German syntax. German speakers naturally use them to add nuance and conditions. The comma before the subordinate clause is obligatory in formal writing."},"examples":[{"german":"Ich rufe an, wenn ich da bin.","english":"I will call when I am there."},{"german":"Wenn es klappt, sage ich dir Bescheid.","english":"If it works out, I will let you know."}],"rewards":{"xp":120,"coins":60},"metadata":{"estimatedMinutes":15,"canDo":"I can build complex sentences using wenn-clauses confidently."}}',
'{"items":[{"word":"Bescheid sagen","translation":"to let someone know","pronunciation":"beh-SHYD ZAH-gen","example":"Ich sage dir Bescheid."},{"word":"sich melden","translation":"to get in touch","pronunciation":"zikh MEL-den","example":"Ich melde mich."},{"word":"ansonsten","translation":"apart from that/otherwise","pronunciation":"an-ZON-sten","example":"Ansonsten geht es mir gut."},{"word":"soweit","translation":"as far as/so far","pronunciation":"zo-VYT","example":"Soweit so gut!"},{"word":"sofern","translation":"provided that/as long as","pronunciation":"zo-FERN","example":"Sofern du kommst."},{"word":"nachdem","translation":"after (subordinating)","pronunciation":"nakh-DEM","example":"Nachdem ich gegessen habe."}]}',
'{"title":"Nachdem + Perfekt — after doing something","pattern":"nachdem ich X gemacht habe, Y-ed (sequence)","explanation":"Nachdem (after) introduces a time clause showing that one action preceded another. The action in the nachdem-clause uses Perfekt, the main clause uses simple present or past: Nachdem ich gegessen habe, trinke ich Kaffee. Nachdem sends verb to end.","examples":[{"sentence":"Nachdem sie angekommen war, rief sie an.","translation":"After she had arrived, she called."},{"sentence":"Ich gehe spazieren, nachdem ich gearbeitet habe.","translation":"I go for a walk after I have worked."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Bescheid sagen'' means?","options":["to let know","to tell","to say","to inform"],"correctAnswer":"to let know"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I will call when I am there.","options":["Ich rufe an, wenn ich da bin.","Wenn ich ankomme, rufe ich an.","Ich bin da, dann rufe ich an.","Ruf mich an!"],"correctAnswer":"Ich rufe an, wenn ich da bin."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Nachdem ich gegessen ___, gehe ich spazieren.","options":["habe","bin","hatte","war"],"correctAnswer":"habe"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: So far so good!","wordBankItems":["Soweit","so","gut","!"],"correctAnswer":"Soweit so gut !"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Sich melden'' means?","options":["to get in touch","to report","to sign up","to answer"],"correctAnswer":"to get in touch"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000078',1,'APPROVED','PUBLISHED',
'{"objectives":["Use weil (because) clauses","Use obwohl (although) clauses","Express reasons and concessions"],"explanation":{"intro":"Weil (because) and obwohl (although) are two of the most important subordinating conjunctions in German. Both send the verb to the end.","culturalNote":"Weil is extremely common in spoken German — sometimes even used as a sentence starter with main clause word order: Ich bleibe zu Hause, weil ich bin müde (colloquial). Formal German always sends verb to end after weil."},"examples":[{"german":"Ich bleibe zu Hause, weil ich krank bin.","english":"I am staying home because I am ill."},{"german":"Er kommt, obwohl er müde ist.","english":"He is coming although he is tired."}],"rewards":{"xp":130,"coins":65},"metadata":{"estimatedMinutes":15,"canDo":"I can use weil and obwohl clauses to give reasons and concessions."}}',
'{"items":[{"word":"weil","translation":"because","pronunciation":"VYL","example":"Weil ich müde bin."},{"word":"obwohl","translation":"although","pronunciation":"op-VOL","example":"Obwohl es schwer ist."},{"word":"trotzdem","translation":"nevertheless/despite","pronunciation":"TROTS-dem","example":"Trotzdem mache ich es."},{"word":"deshalb","translation":"therefore/that''s why","pronunciation":"DES-halp","example":"Deshalb bleibe ich."},{"word":"denn","translation":"because (coord. conj.)","pronunciation":"DEN","example":"Ich bleibe, denn ich bin krank."},{"word":"der Grund","translation":"reason","pronunciation":"dayr GROONT","example":"Aus welchem Grund?"}]}',
'{"title":"Weil vs. denn — both mean because","pattern":"weil + verb-final / denn + main clause word order","explanation":"Both weil and denn mean because. Weil is a subordinating conjunction: verb goes to end. Ich bleibe, weil ich krank bin. Denn is coordinating: normal word order after denn. Ich bleibe, denn ich bin krank. Obwohl (although) always sends verb to end.","examples":[{"sentence":"Er geht nicht hin, obwohl er eingeladen ist.","translation":"He is not going even though he was invited."},{"sentence":"Ich lerne Deutsch, weil ich es interessant finde.","translation":"I am learning German because I find it interesting."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Obwohl'' means?","options":["although","because","therefore","however"],"correctAnswer":"although"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I am staying home because I am ill.","options":["Ich bleibe zu Hause, weil ich krank bin.","Ich bin krank, deshalb bleibe ich.","Obwohl ich krank bin, gehe ich.","Ich bleibe, denn ich bin müde."],"correctAnswer":"Ich bleibe zu Hause, weil ich krank bin."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Er kommt, ___ er müde ist.","options":["obwohl","weil","denn","deshalb"],"correctAnswer":"obwohl"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: That is why I am staying","wordBankItems":["Deshalb","bleibe","ich","."],"correctAnswer":"Deshalb bleibe ich ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"After ''denn'', what word order follows?","options":["main clause order","verb-final","inverted","subordinate"],"correctAnswer":"main clause order"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

